<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import QrcodeVue from 'qrcode.vue'
import { createEventShareLink, getEventShareLinks } from '@/services/dashboardShareService'
const props=defineProps({event:{type:Object,required:true}})
const report=ref(null),loading=ref(false),creating=ref(false),error=ref(''),feedback=ref(''),customLabel=ref(''),showCustomForm=ref(false),qrCodeRef=ref(null)
let controller=null
const links=computed(()=>Array.isArray(report.value?.links)?report.value.links:[])
const qrLink=computed(()=>links.value.find((link)=>link.channel==='qr')||null)
const displayLinks=computed(()=>links.value.filter((link)=>link.channel!=='qr'))
const integer=(value)=>new Intl.NumberFormat('en-NG').format(Number(value||0))
const money=(minor)=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(Number(minor||0)/100)
const message=(err,fallback)=>Object.values(err?.response?.data?.errors||{}).flat().find(Boolean)||err?.response?.data?.message||fallback
const load=async()=>{if(!props.event?.id)return;controller?.abort();controller=new AbortController();loading.value=!report.value;error.value='';try{report.value=await getEventShareLinks(props.event.id,{signal:controller.signal})}catch(err){if(err?.code!=='ERR_CANCELED')error.value=message(err,'We could not load your sharing links.')}finally{loading.value=false}}
const copy=async(value,label)=>{if(!value)return;try{await navigator.clipboard?.writeText(value);feedback.value=`${label} copied.`}catch{feedback.value=value}}
const shareLink=async(link)=>{if(!link?.url)return;const url=encodeURIComponent(link.url),title=encodeURIComponent(props.event.title||'Event'),body=encodeURIComponent(`Get your ticket for ${props.event.title||'this event'}: ${link.url}`);const targets={whatsapp:`https://wa.me/?text=${body}`,x:`https://twitter.com/intent/tweet?text=${title}&url=${url}`,facebook:`https://www.facebook.com/sharer/sharer.php?u=${url}`,linkedin:`https://www.linkedin.com/sharing/share-offsite/?url=${url}`};if(link.channel==='email'){window.location.href=`mailto:?subject=${title}&body=${body}`;return}if(targets[link.channel])window.open(targets[link.channel],'_blank','noopener,noreferrer');else await copy(link.url,`${link.label} link`)}
const create=async()=>{const label=customLabel.value.trim();if(!label||creating.value)return;creating.value=true;error.value='';try{report.value=await createEventShareLink(props.event.id,label);feedback.value=`${label} link created.`;customLabel.value='';showCustomForm.value=false}catch(err){error.value=message(err,'We could not create that link.')}finally{creating.value=false}}
const download=()=>{const canvas=qrCodeRef.value?.$el;if(canvas instanceof HTMLCanvasElement){const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='event-qr.png';a.click()}else if(qrLink.value)void copy(qrLink.value.url,'QR link')}
watch(()=>props.event?.id,(next,previous)=>{if(next&&next!==previous){report.value=null;feedback.value='';void load()}})
onMounted(load);onBeforeUnmount(()=>controller?.abort())
</script>
<template><div class="manage-view active" id="mv-share"><div class="mv-wrap"><div class="mv-header"><div class="mv-eyebrow promote-kicker">Promote</div><div class="mv-h1">Share your <em>event.</em></div><div class="mv-p">Use a different link for each place you share. We'll show you which ones bring people back to buy.</div></div><section v-if="loading" class="share-truth-card" aria-live="polite">Loading sharing links…</section><section v-else-if="error&&!report" class="share-truth-card"><h3>We couldn't load your links.</h3><p>{{error}}</p><button type="button" class="btn btn-ghost" @click="load">Try again</button></section><template v-else-if="report"><section class="share-truth-card"><span class="share-section-label">Event link</span><h3>One clean link for anywhere.</h3><p>This link is untracked. Use the links below when you want to know where sales came from.</p><div class="share-public-link"><code>{{report.public_url}}</code><button type="button" @click="copy(report.public_url,'Event link')">Copy</button></div></section><section class="share-summary-grid"><article class="share-summary-card"><span>Tracked visits</span><strong>{{integer(report.summary?.tracked_visits)}}</strong></article><article class="share-summary-card"><span>Matched buyers</span><strong>{{integer(report.summary?.matched_buyers)}}</strong></article><article class="share-summary-card"><span>Tickets from links</span><strong>{{integer(report.summary?.attributed_tickets_sold)}}</strong></article><article class="share-summary-card"><span>Revenue from links</span><strong>{{money(report.summary?.attributed_revenue_minor)}}</strong></article></section><section class="share-truth-card"><span class="share-section-label">Tracked links</span><h3>See what each place brings.</h3><p>Visits are deduplicated. Sales and revenue only appear after a verified payment.</p><article v-for="link in displayLinks" :key="link.id" class="tracked-link-row"><div class="tracked-link-main"><strong>{{link.label}}</strong><code>{{link.url}}</code></div><div class="tracked-link-stats"><span>Visits <b>{{integer(link.stats?.visits)}}</b></span><span>Buyers <b>{{integer(link.stats?.buyers)}}</b></span><span>Tickets <b>{{integer(link.stats?.tickets_sold)}}</b></span><span>Revenue <b>{{money(link.stats?.revenue_minor)}}</b></span></div><div class="tracked-link-actions"><button type="button" @click="copy(link.url,`${link.label} link`)">Copy</button><button type="button" class="primary" @click="shareLink(link)">Share</button></div></article><div class="custom-link-area"><button v-if="!showCustomForm" type="button" class="custom-link-trigger" @click="showCustomForm=true">Create a link for another group</button><form v-else class="custom-link-form" @submit.prevent="create"><label for="customShareLabel">Link name</label><div class="custom-link-controls"><input id="customShareLabel" v-model="customLabel" maxlength="80" placeholder="e.g. Church group"><button type="submit" class="primary" :disabled="creating">{{creating?'Creating…':'Create'}}</button><button type="button" @click="showCustomForm=false;customLabel=''">Cancel</button></div></form></div></section><section v-if="qrLink" class="share-truth-card qr-source-card"><div><span class="share-section-label">QR source</span><h3>Track posters and flyers too.</h3><p>This QR has its own source link, so offline scans stay separate from your other sharing links.</p><button type="button" class="primary" @click="download">Download QR</button><button type="button" @click="copy(qrLink.url,'QR link')">Copy QR link</button></div><div class="qr-source-visual"><QrcodeVue ref="qrCodeRef" :value="qrLink.url" :size="176" level="M" render-as="canvas"/><div>{{integer(qrLink.stats?.visits)}} tracked visits</div></div></section><section class="share-truth-card direct-card"><div><span class="share-section-label">Direct / untracked</span><h3>{{integer(report.direct?.buyers)}} buyers had no tracked source.</h3><p>That includes people who typed the link, used an untracked copy, or arrived without one of your KakaTickets source links.</p></div><div class="direct-stats"><span>Tickets <b>{{integer(report.direct?.tickets_sold)}}</b></span><span>Revenue <b>{{money(report.direct?.revenue_minor)}}</b></span></div></section><p v-if="feedback" class="share-feedback" role="status">{{feedback}}</p><p v-if="error" class="share-error" role="alert">{{error}}</p></template></div></div></template>
<style scoped>.promote-kicker,.mv-h1 em,.custom-link-trigger{color:var(--color-accent)}.share-truth-card{margin-bottom:18px;padding:24px;border:1px solid var(--color-border);border-radius:16px;background:var(--color-surface);color:var(--color-text)}.share-truth-card p{color:var(--color-muted);line-height:1.6}.share-section-label{color:var(--color-muted);font-size:.68rem;font-weight:700;text-transform:uppercase}.share-public-link,.tracked-link-row,.custom-link-controls{display:flex;gap:10px;align-items:center}.share-public-link{margin-top:16px;padding:10px;border:1px solid var(--color-border);border-radius:9px}.share-public-link code,.tracked-link-main code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--color-muted);flex:1}.share-summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}.share-summary-card{padding:16px;border:1px solid var(--color-border);border-radius:12px;background:var(--color-surface)}.share-summary-card span,.tracked-link-stats span,.direct-stats span{display:block;color:var(--color-muted);font-size:.7rem}.tracked-link-row{padding:16px 0;border-bottom:1px solid var(--color-border);justify-content:space-between}.tracked-link-main{min-width:0;display:grid;gap:5px}.tracked-link-stats{display:flex;gap:12px}.tracked-link-actions{display:flex;gap:7px}button{min-height:38px;padding:0 14px;border:1px solid var(--color-border);border-radius:9px;background:transparent;color:var(--color-text);font:inherit;cursor:pointer}.primary{background:var(--color-accent);border-color:var(--color-accent);color:#fff}.custom-link-area{padding-top:16px}.custom-link-trigger{padding:0;border:0}.custom-link-form{display:grid;gap:8px}.custom-link-controls input{min-height:40px;flex:1;border:1px solid var(--color-border);border-radius:9px;background:var(--color-bg);color:var(--color-text);padding:0 10px}.qr-source-card,.direct-card{display:flex;justify-content:space-between;align-items:center;gap:24px}.qr-source-visual{padding:12px;background:#fff;color:#111;text-align:center}.direct-stats{display:flex;gap:20px}.share-error{color:var(--error)}@media(max-width:760px){.share-summary-grid{grid-template-columns:1fr 1fr}.tracked-link-row,.qr-source-card,.direct-card{align-items:stretch;flex-direction:column}.tracked-link-stats{flex-wrap:wrap}.custom-link-controls{flex-direction:column}}</style>
